var cam=UnityEngine.Camera.main;var pos=cam.transform.position;var rot=cam.transform.rotation;var target=cam.targetTexture;var active=UnityEngine.RenderTexture.active;var rt=new UnityEngine.RenderTexture(960,540,24);var errors=new System.Collections.Generic.List<string>();int views=0;string pose="";
